import random

class Solution:
    def __init__(self, rects: List[List[int]]):
        self.rects = rects

    def pick(self) -> List[int]:
        chosen = None
        count = 0
        for a, b, x, y in self.rects:
            for u in range(a, x + 1):
                for v in range(b, y + 1):
                    count += 1
                    if random.randint(1, count) == 1:
                        chosen = [u, v]
        return chosen

