import java.util.*;

class Solution {
    private final int[][] rects;
    private final int[] prefix;
    private final Random rand = new Random();

    public Solution(int[][] rects) {
        this.rects = rects;
        prefix = new int[rects.length];
        int acc = 0;
        for (int i = 0; i < rects.length; i++) {
            acc += (rects[i][2] - rects[i][0] + 1) * (rects[i][3] - rects[i][1] + 1);
            prefix[i] = acc;
        }
    }

    public int[] pick() {
        int t = 1 + rand.nextInt(prefix[prefix.length - 1]);
        int lo = 0, hi = prefix.length - 1;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (prefix[mid] < t) lo = mid + 1;
            else hi = mid;
        }
        int[] r = rects[lo];
        return new int[]{r[0] + rand.nextInt(r[2] - r[0] + 1),
                         r[1] + rand.nextInt(r[3] - r[1] + 1)};
    }
}

