var Solution = function(rects) {
    this.rects = rects;
    this.prefix = [];
    let acc = 0;
    for (const [a, b, x, y] of rects) {
        acc += (x - a + 1) * (y - b + 1);
        this.prefix.push(acc);
    }
};

Solution.prototype.pick = function() {
    const p = this.prefix;
    const t = 1 + Math.floor(Math.random() * p[p.length - 1]);
    let lo = 0, hi = p.length - 1;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (p[mid] < t) lo = mid + 1;
        else hi = mid;
    }
    const [a, b, x, y] = this.rects[lo];
    return [a + Math.floor(Math.random() * (x - a + 1)),
            b + Math.floor(Math.random() * (y - b + 1))];
};
